SELECT timeSeriesStoreTags(id, tags, '__name__', metric_name) AS x FROM default.`.inner_id.tags.767d9304-dccb-453d-95f4-eb64cc97ae9b` ALL LEFT JOIN (SELECT id, 1 AS matched FROM default.`.inner_id.timeranges.767d9304-dccb-453d-95f4-eb64cc97ae9b` WHERE and(greaterOrEquals(max_time, toDateTime64(toDecimal128('1793494500', 3), 3)), lessOrEquals(min_time, toDateTime64(toDecimal128('1793494800', 3), 3)))) AS time_ranges_subquery USING (id) WHERE and(equals(arrayElement(tags, 'job'), 'job3'), equals(time_ranges_subquery.matched, 1))